def stable_hash(value):return hashlib.sha256(json.dumps(value,sort_keys=True,default=str).encode()).hexdigest()
def parse():
 p=argparse.ArgumentParser();p.add_argument('--cache-dir',required=True);p.add_argument('--fold-manifest',required=True);p.add_argument('--output-dir',required=True);p.add_argument('--fixed-epochs',type=int,default=10);p.add_argument('--max-epochs',type=int,help=argparse.SUPPRESS);p.add_argument('--patience',type=int,help='Ignored in direct-outer fixed-schedule mode');p.add_argument('--seed',type=int,default=42);p.add_argument('--folds',default='all');p.add_argument('--device',default='cuda');p.add_argument('--batch-size',type=int,default=4);p.add_argument('--gradient-accumulation-steps',type=int,default=2);p.add_argument('--learning-rate',type=float,default=2e-4);p.add_argument('--weight-decay',type=float,default=1e-3);p.add_argument('--gradient-clip',type=float,default=1.);p.add_argument('--ema-decay',type=float,default=.98);p.add_argument('--rank-weight',type=float,default=0.);p.add_argument('--n-deterministic-views',type=int,default=4);p.add_argument('--max-seizures-per-view',type=int,default=2);p.add_argument('--max-ez-channels-per-view',type=int,default=24);p.add_argument('--max-nez-channels-per-view',type=int,default=40);p.add_argument('--max-windows-per-phase',type=int,default=4);p.add_argument('--disable-side-features',action='store_true');p.add_argument('--disable-recruitment-dynamics',action='store_true');p.add_argument('--disable-propagation-escape',action='store_true');p.add_argument('--disable-virtual-disconnection',action='store_true');p.add_argument('--disable-cross-seizure-recurrence',action='store_true');p.add_argument('--enable-edge-correction',action='store_true');p.add_argument('--strict',action='store_true');p.add_argument('--smoke-test',action='store_true');p.add_argument('--no-resume-old-checkpoint',action='store_true');return p.parse_args()
def protocol_audit(folds,cohort,selected,fixed_epochs,smoke):
 keys=set(cohort.keys());mf=folds[folds.patient_key.isin(keys)].copy()
 if mf.patient_key.duplicated().any():raise RuntimeError('fold manifest contains duplicate patient records')
 if set(mf.patient_key)!=keys:raise RuntimeError('not every cache patient appears exactly once in fold manifest')
 all_test=set();rows=[]
 for fold in selected:
  test=set(mf[mf.outer_fold==fold].patient_key);train=keys-test
  if not test:raise RuntimeError(f'outer fold {fold} test is empty')
  labels=[cohort.load(k)['outcome_success'] for k in test]
  if not smoke and set(labels)!={0,1}:raise RuntimeError(f'outer fold {fold} lacks success or failure')
  if all_test&test:raise RuntimeError('outer test folds overlap')
  all_test|=test
  rows.append({'outer_fold':fold,'train_patient_ids_hash':stable_hash(sorted(train)),'test_patient_ids_hash':stable_hash(sorted(test)),'train_n':len(train),'test_n':len(test),'train_success':sum(cohort.load(k)['outcome_success'] for k in train),'train_failure':sum(1-cohort.load(k)['outcome_success'] for k in train),'test_success':sum(labels),'test_failure':sum(1-x for x in labels),'train_test_overlap_count':len(train&test)})
 if set(selected)==set(mf.outer_fold.unique()) and all_test!=keys:raise RuntimeError('five-fold test union does not equal complete cohort')
 return {'protocol':PROTOCOL,'n_outer_folds':5,'uses_inner_validation':False,'uses_nested_cv':False,'uses_early_stopping':False,'fixed_epochs':fixed_epochs,'final_model':'ema_final','outer_test_used_for_training':False,'outer_test_used_for_epoch_selection':False,'outer_test_used_for_hyperparameter_selection':False,'threshold':.5,'primary_metric':'pooled_oof_auroc','model_version':MODEL_VERSION,'cache_version':CACHE_VERSION,'folds':rows}
def main():
 a=parse();seed_all(a.seed)
