 if a.max_epochs is not None:print('max-epochs is ignored; use --fixed-epochs',flush=True)
 started=time.time();root=Path(a.cache_dir);out=Path(a.output_dir);out.mkdir(parents=True,exist_ok=True);load_start=time.time();sig=json.loads((root/'cache_signature.json').read_text());cfg=ViewConfig(a.n_deterministic_views,a.max_seizures_per_view,a.max_ez_channels_per_view,a.max_nez_channels_per_view,a.max_windows_per_phase);cohort=CachedCohort(root,root/'cache_manifest.csv',a.seed,cfg);folds=pd.read_csv(a.fold_manifest);cache_load_seconds=time.time()-load_start;selected=sorted(folds.outer_fold.unique()) if a.folds=='all' else [int(x) for x in a.folds.split(',')];audit_protocol=protocol_audit(folds,cohort,selected,a.fixed_epochs,a.smoke_test);js(out/'direct_outer_protocol_audit.json',audit_protocol);device=torch.device(a.device if a.device!='cuda' or torch.cuda.is_available() else 'cpu');kwargs={k:getattr(a,k) for k in ('disable_side_features','disable_recruitment_dynamics','disable_propagation_escape','disable_virtual_disconnection','disable_cross_seizure_recurrence','enable_edge_correction')};probe=TRACEDRELiteV2(**kwargs);audit=model_audit(probe);js(out/'trace_dre_model_audit.json',audit);config={'model_version':MODEL_VERSION,'cache_version':CACHE_VERSION,'cache_signature':sig['signature_hash'],'seed':a.seed,'fixed_epochs':a.fixed_epochs,'learning_rate':a.learning_rate,'weight_decay':a.weight_decay,'ema_decay':a.ema_decay,'rank_weight':a.rank_weight,'view_config':cfg.__dict__,'model_kwargs':kwargs};config_hash=stable_hash(config);print(json.dumps({'protocol':PROTOCOL,'uses_inner_validation':False,'fixed_epochs':a.fixed_epochs,'final_model':'ema_final',**audit,'checkpoint_root':str(out/'checkpoints'/MODEL_VERSION/f'seed_{a.seed}')},indent=2),flush=True)
 allpred=[];history=[];summ=[];artifacts={k:[] for k in ('views','components','seizures','channels','vdr','vdr_nodes','recurrence')};view_audit=[];epoch_times=[];total_windows=0;mf=folds[folds.patient_key.isin(cohort.keys())]
 for fold in selected:
  test=sorted(mf[mf.outer_fold==fold].patient_key);train=sorted(set(cohort.keys())-set(test));print(f'[TRACE-DRE direct outer] fold={fold} train={len(train)} test={len(test)} fixed_epochs={a.fixed_epochs}',flush=True);model=TRACEDRELiteV2(**kwargs).to(device);ema=EMA(model,a.ema_decay);opt=torch.optim.AdamW(model.parameters(),lr=a.learning_rate,weight_decay=a.weight_decay)
  for epoch in range(1,a.fixed_epochs+1):
   stats=train_epoch(model,ema,cohort,train,opt,device,epoch,a);stats.update({'outer_fold':fold,'epoch':epoch,'learning_rate':opt.param_groups[0]['lr']});history.append(stats);epoch_times.append(stats['epoch_wall_time_seconds']);total_windows+=stats['n_windows_encoded'];print(f'[TRACE-DRE] fold {fold} epoch {epoch}/{a.fixed_epochs}: loss={stats["train_total"]:.5f} windows={stats["n_windows_encoded"]}',flush=True)
  cpdir=out/'checkpoints'/MODEL_VERSION/f'seed_{a.seed}'/f'fold_{fold}';cpdir.mkdir(parents=True,exist_ok=True);meta={'model_version':MODEL_VERSION,'cache_version':CACHE_VERSION,'evaluation_protocol':PROTOCOL,'outer_fold':fold,'seed':a.seed,'fixed_epochs':a.fixed_epochs,'uses_inner_validation':False,'uses_early_stopping':False,'outer_test_used_for_selection':False,'uses_true_ez_supernode':True,'virtual_disconnection_version':'TRUE_EZ_VDR_V1','model_kwargs':kwargs,'view_config':cfg.__dict__,'config_hash':config_hash};torch.save({**meta,'selected_model_type':'raw_final','state_dict':model.state_dict()},cpdir/'final_raw.pt');torch.save({**meta,'selected_model_type':'ema_final','state_dict':ema.model.state_dict()},cpdir/'final_ema.pt');ck=torch.load(cpdir/'final_ema.pt',map_location=device,weights_only=False)
  if ck['model_version']!=MODEL_VERSION or ck['cache_version']!=CACHE_VERSION or ck['config_hash']!=config_hash or not ck['uses_true_ez_supernode'] or ck['selected_model_type']!='ema_final':raise RuntimeError('final EMA checkpoint validation failed')
  final_model=TRACEDRELiteV2(**kwargs).to(device);final_model.load_state_dict(ck['state_dict']);pred,art=infer(final_model,cohort,test,device,a.n_deterministic_views)
  for x in pred:x['outer_fold']=fold
  for name,rows in art.items():
   for x in rows:x['outer_fold']=fold
   artifacts[name]+=rows
  allpred+=pred;metrics=metric_row(pd.DataFrame(pred));summ.append({'outer_fold':fold,'train_n':len(train),'test_n':len(test),'fixed_epochs':a.fixed_epochs,'selected_model_type':'ema_final','uses_inner_validation':False,'uses_early_stopping':False,'outer_test_inference_count':1,'test_auroc':metrics['auroc'],'test_accuracy':metrics['accuracy'],'test_balanced_accuracy':metrics['balanced_accuracy'],'test_macro_f1':metrics['macro_f1'],'test_brier':metrics['brier'],'test_success_auprc':metrics['success_auprc'],'loaded_checkpoint_path':str(cpdir/'final_ema.pt')});view_audit += [{'patient_key':k,'outer_fold':fold,'partition':'train' if k in train else 'test','n_views':a.n_deterministic_views} for k in train+test]
 pred=pd.DataFrame(allpred);fold_metrics=pd.DataFrame([{'outer_fold':f,**metric_row(g)} for f,g in pred.groupby('outer_fold')]);pooled=metric_row(pred);summary={**pooled,'fold_mean_auroc':fold_metrics.auroc.mean(),'fold_std_auroc':fold_metrics.auroc.std(ddof=0),'worst_fold_auroc':fold_metrics.auroc.min()};csv(out/'training_history.csv',history);csv(out/'training_summary.csv',summ);csv(out/'fold_metrics.csv',fold_metrics);csv(out/'summary_metrics.csv',[summary]);csv(out/'metrics_by_center.csv',[{'center':c,**metric_row(g)} for c,g in pred.groupby('center')]);csv(out/'bootstrap_ci.csv',bootstrap_ci(pred,2000,a.seed));csv(out/'oof_patient_predictions.csv',pred);csv(out/'view_level_predictions.csv',artifacts['views']);csv(out/'patient_component_scores.csv',artifacts['components']);csv(out/'seizure_component_scores.csv',artifacts['seizures']);csv(out/'channel_escape_scores.csv',artifacts['channels']);csv(out/'virtual_disconnection_scores.csv',artifacts['vdr']);csv(out/'virtual_disconnection_node_audit.csv',artifacts['vdr_nodes']);csv(out/'cross_seizure_recurrence.csv',artifacts['recurrence']);runtime={'cache_load_seconds':cache_load_seconds,'cpu_preprocessing_seconds_during_training':0.,'n_windows_encoded':total_windows,'windows_per_second':total_windows/max(sum(epoch_times),1e-9),'gpu_peak_allocated_gb':torch.cuda.max_memory_allocated(device)/2**30 if device.type=='cuda' else 0.,'gpu_peak_reserved_gb':torch.cuda.max_memory_reserved(device)/2**30 if device.type=='cuda' else 0.,'epoch_wall_time_seconds':epoch_times,'total_wall_time_seconds':time.time()-started};js(out/'runtime_profile.json',runtime);(out/'TRACE_DRE_LITE_V2_1_DIRECT_OUTER_REPORT.md').write_text(f'{MODEL_VERSION} direct outer fixed-epoch evaluation.\n',encoding='utf8');return 0
